        allMatch(s -> s.contains("ERROR")).allMatch(s -> s.contains("isolatedExecutor")).allMatch(s -> s.contains("Exception in thread")).as("Unable to find 'ERROR', 'isolatedExecutor', and 'Exception in thread'").isNotEmpty();
    }
}

