    try (Cluster cluster = init(Cluster.build(3).withConfig(cfg -> cfg.set("paxos_variant", "v2").set("paxos_purge_grace_period", "0s").set("paxos_state_purging", Config.PaxosStatePurging.repaired.toString()).set("truncate_request_timeout", "1000ms")).withoutVNodes().start())) {
