        }).apply(endpoints, executor);
        cleanup.get();
        try {
            insert.get();
        } catch (Throwable t) {
        }
        ExecutorUtils.shutdownNowAndWait(1L, TimeUnit.MINUTES, executor);
        Assert.assertFalse(hasUncommittedQuorum(cluster, KEYSPACE, TABLE));
        assertLowBoundPurged(cluster);
    }
}

