public void warmCacheLoadsAllEntries() {
    IRoleManager roleManager = new AuthTestUtils.LocalCassandraRoleManager();
    roleManager.setup();
    for (RoleResource r : ALL_ROLES) roleManager.createRole(AuthenticatedUser.ANONYMOUS_USER, r, new RoleOptions());
