@Test
public void rejectInvocationOfUnknownMethod() throws Throwable {
    // Grant ALL permissions on the root resource, so we know that it's
    // the unknown method that causes the authz rejection. Of course, this
    // isn't foolproof but it's something.
    Set<PermissionDetails> allPerms = Permission.ALL.stream().map(perm -> permission(role1, JMXResource.root(), perm)).collect(Collectors.toSet());
    Map<RoleResource, Set<PermissionDetails>> permissions = ImmutableMap.of(role1, allPerms);
    AuthorizationProxy proxy = new ProxyBuilder().isAuthzRequired(() -> true).isSuperuser((role) -> false).getPermissions(permissions::get).build();
    assertFalse(proxy.authorize(subject(role1.getRoleName()), "unKnownMethod", new Object[] { ObjectName.getInstance(osBean.getObjectName()) }));
}

@Test
public void rejectInvocationOfRestrictedMethods() throws Throwable {
    String[] methods = { "createMBean", "deserialize", "getClassLoader", "getClassLoaderFor", "instantiate", "registerMBean", "unregisterMBean" };
    // Hardcode the superuser status check to return true, so any allowed method can be invoked.
    AuthorizationProxy proxy = new ProxyBuilder().isAuthzRequired(() -> true).isSuperuser((role) -> true).build();
    for (String method : methods) // the arguments array isn't significant, so it can just be empty
    assertFalse(proxy.authorize(subject(role1.getRoleName()), method, new Object[0]));
}

