@Test
public void testFunctionResourceNameConversion() {
    assertEquals(FunctionResource.root(), Resources.fromName("functions"));
    assertEquals("functions", FunctionResource.root().getName());
    assertEquals(FunctionResource.keyspace("ks1"), Resources.fromName("functions/ks1"));
    assertEquals("functions/ks1", FunctionResource.keyspace("ks1").getName());
    assertEquals(FunctionResource.function("ks1", "f1", Collections.emptyList()), Resources.fromName("functions/ks1/f1[]"));
    // this is actually supported by an explicit check in TypeParser
    assertEquals(FunctionResource.function("ks1", "f1", Arrays.asList(Int32Type.instance, DoubleType.instance)), Resources.fromName("functions/ks1/f1[Int32Type^DoubleType]"));
    assertEquals("functions/ks1/f1[]", FunctionResource.function("ks1", "f1", Collections.emptyList()).getName());
    assertEquals(FunctionResource.function("ks1", "f1", Arrays.asList(Int32Type.instance, DoubleType.instance)), Resources.fromName("functions/ks1/f1[org.apache.cassandra.db.marshal.Int32Type^org.apache.cassandra.db.marshal.DoubleType]"));
