            executor.setMaximumPoolSize(0);
            Assert.assertEquals(0, busyExecutor.getNotifiedMaxPoolSize());
            Thread.sleep(250);
            assertMaxTaskConcurrency(executor, 4);
            Assert.assertEquals(4, busyExecutor.getNotifiedMaxPoolSize());
        }
    } finally {
        executor.shutdown();
    }
}

