    assertThatThrownBy(() -> new DataRateSpec.LongBytesPerSecondBound(Long.MAX_VALUE)).isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Invalid data rate: 9.223372036854776E18 bytes_per_second. " + "It shouldn't be more than 9223372036854775806 in bytes_per_second");
    assertThatThrownBy(() -> new DataRateSpec.LongBytesPerSecondBound("9007199254740992KiB/s")).isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Invalid data rate: 9007199254740992KiB/s. " + "It shouldn't be more than 9223372036854775806 in bytes_per_second");
    assertThatThrownBy(() -> new DataRateSpec.LongBytesPerSecondBound("8796093022208MiB/s")).isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Invalid data rate: 8796093022208MiB/s. " + "It shouldn't be more than 9223372036854775806 in bytes_per_second");
