    // not empty collections
    execute("INSERT INTO %s (k, l, fl, s, fs, m, fm)  VALUES (1, ?, ?, ?, ?, ?, ?)", list(bigdecimal1, bigdecimal2), list(bigdecimal1, bigdecimal2), set(bigdecimal1, bigdecimal2), set(bigdecimal1, bigdecimal2), map(bigdecimal1, bigdecimal2, bigdecimal2, bigdecimal1), map(bigdecimal1, bigdecimal2, bigdecimal2, bigdecimal1));
    assertRows(execute("SELECT map_keys(m), map_keys(fm) FROM %s"), row(set(bigdecimal1, bigdecimal2), set(bigdecimal1, bigdecimal2)));
