    assertRows(execute("SELECT collection_count(fl), collection_count(fs), collection_count(fm) FROM %s"), row(2, 2, 2));
    assertRows(execute("SELECT collection_min(l), collection_min(s), collection_min(fl), collection_min(fs) FROM %s"), row(bigdecimal1, bigdecimal1, bigdecimal1, bigdecimal1));
    assertRows(execute("SELECT collection_max(l), collection_max(s), collection_max(fl), collection_max(fs) FROM %s"), row(bigdecimal2, bigdecimal2, bigdecimal2, bigdecimal2));
