    assertInvalidThrowMessage("the operation 'bigint / tinyint' failed: / by zero", OperationExecutionException.class, "SELECT d / a FROM %s WHERE a = 0 AND b = 2");
    assertInvalidThrowMessage("the operation 'smallint / smallint' failed: / by zero", OperationExecutionException.class, "SELECT a FROM %s WHERE a = 0 AND b = 10/0");
