@Test
public void test() throws Throwable {
    String createStatement = String.format("CREATE TABLE %s.%s (c text, %s text, PRIMARY KEY (c, %s))", KEYSPACE, keyword, keyword, keyword, keyword);
    logger.info(createStatement);
    if (isReserved) {
        try {
            schemaChange(createStatement);
            Assert.fail(String.format("Reserved keyword %s should not have parsed", keyword));
        } catch (// SyntaxException is wrapped by CQLTester
        RuntimeException ignore) {
            Assert.assertEquals(SyntaxException.class, ignore.getCause().getClass());
        }
    } else // not a reserved word
    {
        /* Create the table using the keyword as a tablename and column name, then call describe and re-create it
             * using the create_statement result.
             */
        schemaChange(createStatement);
        String describeStatement = String.format("DESCRIBE TABLE %s.%s", KEYSPACE, keyword);
        UntypedResultSet rs = execute(describeStatement);
        UntypedResultSet.Row row = rs.one();
        String describedCreateStatement = row.getString("create_statement");
        String recreateStatement = describedCreateStatement.replace(KEYSPACE, KEYSPACE_PER_TEST);
        logger.info(recreateStatement);
        schemaChange(recreateStatement);
        /* Check it is possible to insert and select from the table/column, with the keyword used in the
             * where clause
             */
        String insertStatement = String.format("INSERT INTO %s.%s(c,%s) VALUES ('x', '%s')", KEYSPACE, keyword, keyword, keyword);
        logger.info(insertStatement);
        execute(insertStatement);
        String selectStatement = String.format("SELECT c, %s FROM %s.%s WHERE c = 'x' AND %s >= ''", keyword, KEYSPACE, keyword, keyword);
        logger.info(selectStatement);
        rs = execute(selectStatement);
        row = rs.one();
        String value = row.getString(keyword.toLowerCase());
        Assert.assertEquals(keyword, value);
        /* Make a materialized view using the fields (cannot re-use the name as MV must be in same keyspace).
             * Added as CASSANDRA-11803 motivated adding the reserved/unreserved distinction
            */
        String createMV = String.format("CREATE MATERIALIZED VIEW %s.mv_%s AS %s PRIMARY KEY (c, %s)", KEYSPACE, keyword, selectStatement, keyword);
        logger.info(createMV);
        schemaChange(createMV);
    }
}

@Test
public void testPrecisionTime_getNext_simple() {
    PrecisionTime.set(DEFAULT_MILLIS, DEFAULT_NANOS);
    long millis = DEFAULT_MILLIS - 100;
    int count = 1;
    PrecisionTime next = PrecisionTime.getNext(millis, count);
    Assert.assertEquals(millis, next.millis);
    Assert.assertEquals(DEFAULT_NANOS - count, next.nanos);
    next = PrecisionTime.getNext(millis, count);
    Assert.assertEquals(millis, next.millis);
    Assert.assertEquals(DEFAULT_NANOS - (count * 2), next.nanos);
}

@Test
public void testPrecisionTime_getNext_Mulitple() {
    PrecisionTime.set(DEFAULT_MILLIS, DEFAULT_NANOS);
    long millis = DEFAULT_MILLIS - 100;
    int count = DEFAULT_NANOS / 2;
    PrecisionTime next = PrecisionTime.getNext(millis, count);
    Assert.assertEquals(millis, next.millis);
    Assert.assertEquals(DEFAULT_NANOS - count, next.nanos);
}

@Test
public void testPrecisionTime_getNext_RollOverNanos() {
    final int remainingNanos = 0;
    PrecisionTime.set(DEFAULT_MILLIS, remainingNanos);
    long millis = DEFAULT_MILLIS;
    int count = 1;
    PrecisionTime next = PrecisionTime.getNext(millis, count);
    Assert.assertEquals(millis - 1, next.millis);
    Assert.assertEquals(DEFAULT_NANOS - count, next.nanos);
    next = PrecisionTime.getNext(millis, count);
    Assert.assertEquals(millis - 1, next.millis);
    Assert.assertEquals(DEFAULT_NANOS - (count * 2), next.nanos);
}

@Test
public void testPrecisionTime_getNext_BorkedClock() {
    final int remainingNanos = 1;
    PrecisionTime.set(DEFAULT_MILLIS, remainingNanos);
    long millis = DEFAULT_MILLIS + 100;
    int count = 1;
    PrecisionTime next = PrecisionTime.getNext(millis, count);
    Assert.assertEquals(DEFAULT_MILLIS, next.millis);
    Assert.assertEquals(remainingNanos - count, next.nanos);
    // this should roll the clock
    next = PrecisionTime.getNext(millis, count);
    Assert.assertEquals(DEFAULT_MILLIS - 1, next.millis);
    Assert.assertEquals(DEFAULT_NANOS - count, next.nanos);
}

