@Test
public void testSchemaChangeDuringPaging() {
    SimpleStatement stmt = new SimpleStatement("DESCRIBE KEYSPACES");
    stmt.setFetchSize(1);
    ResultSet rs = executeNet(ProtocolVersion.CURRENT, stmt);
    Iterator<Row> iter = rs.iterator();
    assertTrue(iter.hasNext());
    iter.next();
    createKeyspace("CREATE KEYSPACE %s WITH REPLICATION = {'class' : 'SimpleStrategy', 'replication_factor' : 1};");
    try {
        iter.next();
        fail("Expected InvalidQueryException");
    } catch (InvalidQueryException e) {
        assertEquals(DescribeStatement.SCHEMA_CHANGED_WHILE_PAGING_MESSAGE, e.getMessage());
    }
}

@Test
public void testDescribeFunctionAndAggregate() throws Throwable {
    String fNonOverloaded = createFunction(KEYSPACE_PER_TEST, "", "CREATE OR REPLACE FUNCTION %s() " + "CALLED ON NULL INPUT " + "RETURNS int " + "LANGUAGE java " + "AS 'throw new RuntimeException();';");
    String fOverloaded = createFunction(KEYSPACE_PER_TEST, "int, ascii", "CREATE FUNCTION %s (input int, other_in ascii) " + "RETURNS NULL ON NULL INPUT " + "RETURNS text " + "LANGUAGE java " + "AS 'return \"Hello World\";'");
    createFunctionOverload(fOverloaded, "text, ascii", "CREATE FUNCTION %s (input text, other_in ascii) " + "RETURNS NULL ON NULL INPUT " + "RETURNS text " + "LANGUAGE java " + "AS 'return \"Hello World\";'");
    for (String describeKeyword : new String[] { "DESCRIBE", "DESC" }) {
        assertRowsNet(executeDescribeNet(describeKeyword + " FUNCTION " + fNonOverloaded), row(KEYSPACE_PER_TEST, "function", shortFunctionName(fNonOverloaded) + "()", "CREATE FUNCTION " + fNonOverloaded + "()\n" + "    CALLED ON NULL INPUT\n" + "    RETURNS int\n" + "    LANGUAGE java\n" + "    AS $$throw new RuntimeException();$$;"));
        assertRowsNet(executeDescribeNet(describeKeyword + " FUNCTION " + fOverloaded), row(KEYSPACE_PER_TEST, "function", shortFunctionName(fOverloaded) + "(int, ascii)", "CREATE FUNCTION " + fOverloaded + "(input int, other_in ascii)\n" + "    RETURNS NULL ON NULL INPUT\n" + "    RETURNS text\n" + "    LANGUAGE java\n" + "    AS $$return \"Hello World\";$$;"), row(KEYSPACE_PER_TEST, "function", shortFunctionName(fOverloaded) + "(text, ascii)", "CREATE FUNCTION " + fOverloaded + "(input text, other_in ascii)\n" + "    RETURNS NULL ON NULL INPUT\n" + "    RETURNS text\n" + "    LANGUAGE java\n" + "    AS $$return \"Hello World\";$$;"));
        assertRowsNet(executeDescribeNet(describeKeyword + " FUNCTIONS"), row(KEYSPACE_PER_TEST, "function", shortFunctionName(fNonOverloaded) + "()"), row(KEYSPACE_PER_TEST, "function", shortFunctionName(fOverloaded) + "(int, ascii)"), row(KEYSPACE_PER_TEST, "function", shortFunctionName(fOverloaded) + "(text, ascii)"));
    }
    String fIntState = createFunction(KEYSPACE_PER_TEST, "int, int", "CREATE FUNCTION %s (state int, add_to int) " + "CALLED ON NULL INPUT " + "RETURNS int " + "LANGUAGE java " + "AS 'return state + add_to;'");
    String fFinal = createFunction(KEYSPACE_PER_TEST, "int", "CREATE FUNCTION %s (state int) " + "RETURNS NULL ON NULL INPUT " + "RETURNS int " + "LANGUAGE java " + "AS 'return state;'");
    String aNonDeterministic = createAggregate(KEYSPACE_PER_TEST, "int", format("CREATE AGGREGATE %%s(int) " + "SFUNC %s " + "STYPE int " + "INITCOND 42", shortFunctionName(fIntState)));
    String aDeterministic = createAggregate(KEYSPACE_PER_TEST, "int", format("CREATE AGGREGATE %%s(int) " + "SFUNC %s " + "STYPE int " + "FINALFUNC %s ", shortFunctionName(fIntState), shortFunctionName(fFinal)));
    for (String describeKeyword : new String[] { "DESCRIBE", "DESC" }) {
        assertRowsNet(executeDescribeNet(describeKeyword + " AGGREGATE " + aNonDeterministic), row(KEYSPACE_PER_TEST, "aggregate", shortFunctionName(aNonDeterministic) + "(int)", "CREATE AGGREGATE " + aNonDeterministic + "(int)\n" + "    SFUNC " + shortFunctionName(fIntState) + "\n" + "    STYPE int\n" + "    INITCOND 42;"));
        assertRowsNet(executeDescribeNet(describeKeyword + " AGGREGATE " + aDeterministic), row(KEYSPACE_PER_TEST, "aggregate", shortFunctionName(aDeterministic) + "(int)", "CREATE AGGREGATE " + aDeterministic + "(int)\n" + "    SFUNC " + shortFunctionName(fIntState) + "\n" + "    STYPE int\n" + "    FINALFUNC " + shortFunctionName(fFinal) + ";"));
        assertRowsNet(executeDescribeNet(describeKeyword + " AGGREGATES"), row(KEYSPACE_PER_TEST, "aggregate", shortFunctionName(aNonDeterministic) + "(int)"), row(KEYSPACE_PER_TEST, "aggregate", shortFunctionName(aDeterministic) + "(int)"));
    }
}

