    TableId id = Schema.instance.getTableMetadata(KEYSPACE_PER_TEST, table).id;
    String tableCreateStatement = "CREATE TABLE " + KEYSPACE_PER_TEST + "." + table + " (
" + "    pk1 text,
" + "    pk2 int,
" + "    c int,
" + "    s decimal static,
" + "    v1 text,
" + "    v2 int,
" + "    v3 int,
" + "    PRIMARY KEY ((pk1, pk2), c)
