@Test
public void testDescribeTableAndMaterializedViewWithClustringOrder() throws Throwable {
    String table = createTable(KEYSPACE_PER_TEST, "CREATE TABLE IF NOT EXISTS %s (pk1 int, pk2 int, ck1 int, ck2 int, reg1 int, reg2 list<int>, reg3 int, PRIMARY KEY ((pk1, pk2), ck1, ck2)) WITH CLUSTERING ORDER BY (ck1 ASC, ck2 DESC);");
    execute("CREATE MATERIALIZED VIEW IF NOT EXISTS " + KEYSPACE_PER_TEST + ".mv AS SELECT * FROM " + KEYSPACE_PER_TEST + "." + table + " WHERE pk2 IS NOT NULL AND pk1 IS NOT NULL AND ck2 IS NOT NULL AND ck1 IS NOT NULL PRIMARY KEY ((pk2, pk1), ck2, ck1)");
    String tableCreateStatement = "CREATE TABLE " + KEYSPACE_PER_TEST + "." + table + " (
" + "    pk1 int,
" + "    pk2 int,
" + "    ck1 int,
" + "    ck2 int,
" + "    reg1 int,
" + "    reg3 int,
" + "    reg2 list<int>,
" + "    PRIMARY KEY ((pk1, pk2), ck1, ck2)
" + ") WITH CLUSTERING ORDER BY (ck1 ASC, ck2 DESC)
" + "    AND " + tableParametersCql();
    String mvCreateStatement = "CREATE MATERIALIZED VIEW " + KEYSPACE_PER_TEST + ".mv AS
" + "    SELECT *
" + "    FROM " + KEYSPACE_PER_TEST + "." + table + "
" + "    WHERE pk2 IS NOT NULL AND pk1 IS NOT NULL AND ck2 IS NOT NULL AND ck1 IS NOT NULL
" + "    PRIMARY KEY ((pk2, pk1), ck2, ck1)
" + " WITH CLUSTERING ORDER BY (ck2 DESC, ck1 ASC)
" + "    AND " + mvParametersCql();
    try {
        assertRowsNet(executeDescribeNet("DESCRIBE TABLE " + KEYSPACE_PER_TEST + "." + table), row(KEYSPACE_PER_TEST, "table", table, tableCreateStatement));
        assertRowsNet(executeDescribeNet("DESCRIBE MATERIALIZED VIEW " + KEYSPACE_PER_TEST + ".mv"), row(KEYSPACE_PER_TEST, "materialized_view", "mv", mvCreateStatement));
    } finally {
        execute("DROP MATERIALIZED VIEW " + KEYSPACE_PER_TEST + ".mv");
    }
}

