    execute("UPDATE %s SET l[1] = ? WHERE k = 10", unset());
    assertRows(execute("SELECT l FROM %s WHERE k = 10"), row(l));
    // set in index
    assertInvalidMessage("Invalid unset value for list index", "UPDATE %s SET l[?] = 'foo' WHERE k = 10", unset());
