    assertRows(execute("SELECT s['1'], fs['f1'], ss['s1'], fss['fs1'] FROM %s WHERE k = 0 AND c = 0"), row("1", "f1", "s1", "fs1"));
    assertRows(execute("SELECT k, c, l, s['1'], fs['f1'], ss['s1'], fss['fs1'], o FROM %s WHERE k = 0"), row(0, 0, "foobar", "1", "f1", "s1", "fs1", 42), row(0, 1, "foobar", null, null, "s1", "fs1", 42));
    assertColumnNames(execute("SELECT k, l, s['1'], o FROM %s WHERE k = 0"), "k", "l", "s['1']", "o");
    assertRows(execute("SELECT k, l, s['22'], o FROM %s WHERE k = 0 AND c = 0"), row(0, "foobar", "22", 42));
    assertRows(execute("SELECT k, l, s['333'], o FROM %s WHERE k = 0 AND c = 0"), row(0, "foobar", "333", 42));
    assertRows(execute("SELECT k, l, s['foobar'], o FROM %s WHERE k = 0 AND c = 0"), row(0, "foobar", null, 42));
    assertRows(execute("SELECT k, l, s['1'..'22'], o FROM %s WHERE k = 0 AND c = 0"), row(0, "foobar", set("1", "22"), 42));
    assertColumnNames(execute("SELECT k, l, s[''..'22'], o FROM %s WHERE k = 0"), "k", "l", "s[''..'22']", "o");
    assertRows(execute("SELECT k, l, s[''..'23'], o FROM %s WHERE k = 0 AND c = 0"), row(0, "foobar", set("1", "22", "22_2"), 42));
    assertRows(execute("SELECT k, l, s['2'..'3'], o FROM %s WHERE k = 0 AND c = 0"), row(0, "foobar", set("22", "22_2"), 42));
    assertRows(execute("SELECT k, l, s['22'..], o FROM %s WHERE k = 0"), row(0, "foobar", set("22", "22_2", "333"), 42), row(0, "foobar", set("22", "333"), 42));
    assertRows(execute("SELECT k, l, s[..'22'], o FROM %s WHERE k = 0"), row(0, "foobar", set("1", "22"), 42), row(0, "foobar", set("22"), 42));
    assertRows(execute("SELECT k, l, s, o FROM %s WHERE k = 0"), row(0, "foobar", set("1", "22", "22_2", "333"), 42), row(0, "foobar", set("22", "333"), 42));
}

