@Test
public void testJsonOrdering() throws Throwable {
    createTable("CREATE TABLE %s(a INT, b INT, PRIMARY KEY (a, b))");
    execute("INSERT INTO %s(a, b) VALUES (20, 30);");
    execute("INSERT INTO %s(a, b) VALUES (100, 200);");
    assertRows(execute("SELECT JSON a, b FROM %s WHERE a IN (20, 100) ORDER BY b"), row("{\"a\": 20, \"b\": 30}"), row("{\"a\": 100, \"b\": 200}"));
    assertRows(execute("SELECT JSON a, b FROM %s WHERE a IN (20, 100) ORDER BY b DESC"), row("{\"a\": 100, \"b\": 200}"), row("{\"a\": 20, \"b\": 30}"));
    assertRows(execute("SELECT JSON a FROM %s WHERE a IN (20, 100) ORDER BY b DESC"), row("{\"a\": 100}"), row("{\"a\": 20}"));
    // Check ordering with alias
    assertRows(execute("SELECT JSON a, b as c FROM %s WHERE a IN (20, 100) ORDER BY b"), row("{\"a\": 20, \"c\": 30}"), row("{\"a\": 100, \"c\": 200}"));
    assertRows(execute("SELECT JSON a, b as c FROM %s WHERE a IN (20, 100) ORDER BY b DESC"), row("{\"a\": 100, \"c\": 200}"), row("{\"a\": 20, \"c\": 30}"));
    // Check ordering with CAST
    assertRows(execute("SELECT JSON a, CAST(b AS FLOAT) FROM %s WHERE a IN (20, 100) ORDER BY b"), row("{\"a\": 20, \"cast(b as float)\": 30.0}"), row("{\"a\": 100, \"cast(b as float)\": 200.0}"));
    assertRows(execute("SELECT JSON a, CAST(b AS FLOAT) FROM %s WHERE a IN (20, 100) ORDER BY b DESC"), row("{\"a\": 100, \"cast(b as float)\": 200.0}"), row("{\"a\": 20, \"cast(b as float)\": 30.0}"));
}

