        if (r[0].equals(1))
            assertNull(r[3]);
        else
            assertTrue(r[3] instanceof Integer || r[2] instanceof Long);
    }
    res = getRows(execute("SELECT k, c, writetime(c), blobAsInt(intAsBlob(ttl(c))) FROM %s"));
