    assertInvalidMessage("cannot be frozen; remove frozen<> modifier", "CREATE OR REPLACE FUNCTION " + KEYSPACE + ".frozenReturnType(values " + myType + ") " + "CALLED ON NULL INPUT " + "RETURNS frozen<" + myType + "> " + "LANGUAGE java\n" + "AS 'return values;';");
    String functionName = createFunction(KEYSPACE, myType, "CREATE FUNCTION %s (values " + myType + ") " + "CALLED ON NULL INPUT " + "RETURNS text " + "LANGUAGE java\n" + "AS 'return values.toString();';");
