" + "    }
" + '
' + "    Object field = new Object();
" + '
' + "    {
" + "Math.sin(1d);", "Java UDF validation failed: [field declared: field, initializer declared]");
    assertInvalidByteCode('
' + "return 0d;
" + "    }
" + '
' + "    {
" + "Math.sin(1d);", "Java UDF validation failed: [initializer declared]");
    assertInvalidByteCode('
' + "return 0d;
" + "    }
" + '
' + "    static
