    // delete both fields at once
    execute("INSERT INTO %s (k, v) VALUES (?, ?)", 0, userType("a", 0, "b", "abc"));
    execute("DELETE v.a, v.b FROM %s WHERE k = ?", 0);
    assertRows(execute("SELECT * FROM %s WHERE k = ?", 0), row(0, null));
    // same, but reverse field order
    execute("INSERT INTO %s (k, v) VALUES (?, ?)", 0, userType("a", 0, "b", "abc"));
