    assertWritetimeAndTTL("s[2]", NO_TIMESTAMP, NO_TTL);
    assertWritetimeAndTTL("s[..0]", NO_TIMESTAMP, NO_TTL);
    assertWritetimeAndTTL("s[..1]", timestamps(TIMESTAMP_1), ttls(NO_TTL));
