@Test
public void testLogbackReload() throws Throwable {
    // see https://issues.apache.org/jira/browse/CASSANDRA-11033
    // make logback's scan interval 1ms - boilerplate, but necessary for this test
    configureLogbackScanPeriod(1L);
    try {
        createTable("CREATE TABLE %s (" + "   year int PRIMARY KEY," + "   country text," + "   title text)");
        String[] countries = Locale.getISOCountries();
        ThreadLocalRandom rand = ThreadLocalRandom.current();
        for (int i = 0; i < 10000; i++) {
            execute("INSERT INTO %s (year, country, title) VALUES (1980,?,?)", countries[rand.nextInt(countries.length)], "title-" + i);
        }
        String albumCountByCountry = createFunction(KEYSPACE, "map<text,bigint>,text,text", "CREATE FUNCTION IF NOT EXISTS %s(state map<text,bigint>,country text, album_title text)\n" + " RETURNS NULL ON NULL INPUT\n" + " RETURNS map<text,bigint>\n" + " LANGUAGE java\n" + " AS $$\n" + "   if(state.containsKey(country)) {\n" + "       Long newCount = (Long)state.get(country) + 1;\n" + "       state.put(country, newCount);\n" + "   } else {\n" + "       state.put(country, 1L);\n" + "   }\n" + "   return state;\n" + " $$;");
        String releasesByCountry = createAggregate(KEYSPACE, "text, text", " CREATE AGGREGATE IF NOT EXISTS %s(text, text)\n" + " SFUNC " + shortFunctionName(albumCountByCountry) + '\n' + " STYPE map<text,bigint>\n" + " INITCOND { };");
        long tEnd = System.currentTimeMillis() + 150;
        while (System.currentTimeMillis() < tEnd) {
            execute("SELECT " + releasesByCountry + "(country,title) FROM %s WHERE year=1980");
        }
    } finally {
        configureLogbackScanPeriod(60000L);
    }
}

@Test
public void testOrReplaceOptionals() throws Throwable {
    String fState = createFunction(KEYSPACE, "list<text>, int", "CREATE FUNCTION %s(s list<text>, i int) " + "CALLED ON NULL INPUT " + "RETURNS list<text> " + "LANGUAGE java " + "AS 'if (i != null) s.add(String.valueOf(i)); return s;'");
    String fFinal = shortFunctionName(createFunction(KEYSPACE, "list<text>", "CREATE FUNCTION %s(s list<text>) " + "CALLED ON NULL INPUT " + "RETURNS list<text> " + "LANGUAGE java " + "AS 'return s;'"));
    String a = createAggregate(KEYSPACE, "int", "CREATE AGGREGATE %s(int) " + "SFUNC " + shortFunctionName(fState) + ' ' + "STYPE list<text> ");
    checkOptionals(a, null, null);
    String ddlPrefix = "CREATE OR REPLACE AGGREGATE " + a + "(int) " + "SFUNC " + shortFunctionName(fState) + ' ' + "STYPE list<text> ";
    // Test replacing INITCOND
    execute(ddlPrefix + "INITCOND [  ] ");
    checkOptionals(a, null, "[]");
