    assertAlterTableThrowsException(ConfigurationException.class, "The 'class_name' option must be specified.", "ALTER TABLE %s" + " WITH memtable = 'test_empty_class';");
    assertAlterTableThrowsException(ConfigurationException.class, "Memtable class org.apache.cassandra.db.memtable.SkipListMemtable does not accept any futher parameters, but {invalid=throw} were given.", "ALTER TABLE %s" + " WITH memtable = 'test_invalid_param';");
