@Test
public void testGroupByWithRangeNamesQueryWithoutPaging() throws Throwable {
    createTable("CREATE TABLE %s (a int, b int, c int, d int, primary key (a, b, c))" + compactOption);
    for (int i = 1; i < 5; i++) for (int j = 1; j < 5; j++) for (int k = 1; k < 5; k++) execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", i, j, k, i + j);
    // Makes sure that we have some tombstones
    execute("DELETE FROM %s WHERE a = 3");
    // Range queries
    assertRows(execute("SELECT a, b, d, count(b), max(d) FROM %s WHERE b = 1 and c IN (1, 2) GROUP BY a ALLOW FILTERING"), row(1, 1, 2, 2L, 2), row(2, 1, 3, 2L, 3), row(4, 1, 5, 2L, 5));
    assertRows(execute("SELECT a, b, d, count(b), max(d) FROM %s WHERE b = 1 and c IN (1, 2) GROUP BY a, b ALLOW FILTERING"), row(1, 1, 2, 2L, 2), row(2, 1, 3, 2L, 3), row(4, 1, 5, 2L, 5));
    assertRows(execute("SELECT a, b, d, count(b), max(d) FROM %s WHERE b IN (1, 2) and c IN (1, 2) GROUP BY a, b ALLOW FILTERING"), row(1, 1, 2, 2L, 2), row(1, 2, 3, 2L, 3), row(2, 1, 3, 2L, 3), row(2, 2, 4, 2L, 4), row(4, 1, 5, 2L, 5), row(4, 2, 6, 2L, 6));
    // Range queries with LIMIT
    assertRows(execute("SELECT a, b, d, count(b), max(d) FROM %s WHERE b = 1 and c IN (1, 2) GROUP BY a LIMIT 5 ALLOW FILTERING"), row(1, 1, 2, 2L, 2), row(2, 1, 3, 2L, 3), row(4, 1, 5, 2L, 5));
    assertRows(execute("SELECT a, b, d, count(b), max(d) FROM %s WHERE b = 1 and c IN (1, 2) GROUP BY a, b LIMIT 3 ALLOW FILTERING"), row(1, 1, 2, 2L, 2), row(2, 1, 3, 2L, 3), row(4, 1, 5, 2L, 5));
    assertRows(execute("SELECT a, b, d, count(b), max(d) FROM %s WHERE b IN (1, 2) and c IN (1, 2) GROUP BY a, b LIMIT 3 ALLOW FILTERING"), row(1, 1, 2, 2L, 2), row(1, 2, 3, 2L, 3), row(2, 1, 3, 2L, 3));
    // Range queries with PER PARTITION LIMIT
    assertRows(execute("SELECT a, b, d, count(b), max(d) FROM %s WHERE b = 1 and c IN (1, 2) GROUP BY a, b PER PARTITION LIMIT 2 ALLOW FILTERING"), row(1, 1, 2, 2L, 2), row(2, 1, 3, 2L, 3), row(4, 1, 5, 2L, 5));
    assertRows(execute("SELECT a, b, d, count(b), max(d) FROM %s WHERE b IN (1, 2) and c IN (1, 2) GROUP BY a, b PER PARTITION LIMIT 1 ALLOW FILTERING"), row(1, 1, 2, 2L, 2), row(2, 1, 3, 2L, 3), row(4, 1, 5, 2L, 5));
    // Range queries with PER PARTITION LIMIT and LIMIT
    assertRows(execute("SELECT a, b, d, count(b), max(d) FROM %s WHERE b = 1 and c IN (1, 2) GROUP BY a, b PER PARTITION LIMIT 2 LIMIT 5 ALLOW FILTERING"), row(1, 1, 2, 2L, 2), row(2, 1, 3, 2L, 3), row(4, 1, 5, 2L, 5));
    assertRows(execute("SELECT a, b, d, count(b), max(d) FROM %s WHERE b IN (1, 2) and c IN (1, 2) GROUP BY a, b PER PARTITION LIMIT 1 LIMIT 2 ALLOW FILTERING"), row(1, 1, 2, 2L, 2), row(2, 1, 3, 2L, 3));
}

