        assertRows(execute("SELECT * FROM %s WHERE a >= 2 AND c >= 4 AND d <= 8 ALLOW FILTERING"), row(2, 3, 7, 8));
    });
    // Checks filtering with null
    assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE d = null");
    assertInvalidMessage("Unsupported null value for column a", "SELECT * FROM %s WHERE a = null ALLOW FILTERING");
    assertInvalidMessage("Unsupported null value for column a", "SELECT * FROM %s WHERE a > null ALLOW FILTERING");
    // Checks filtering with unset
    assertInvalidMessage("Unsupported unset value for column a", "SELECT * FROM %s WHERE a = ? ALLOW FILTERING", unset());
    assertInvalidMessage("Unsupported unset value for column a", "SELECT * FROM %s WHERE a > ? ALLOW FILTERING", unset());
    //----------------------------------------------
    // Test COMPACT table without clustering columns
    //----------------------------------------------
    createTable("CREATE TABLE %s (a int primary key, b int, c int) WITH COMPACT STORAGE");
    execute("INSERT INTO %s (a, b, c) VALUES (1, 2, 4)");
    execute("INSERT INTO %s (a, b, c) VALUES (2, 1, 6)");
    execute("INSERT INTO %s (a, b, c) VALUES (3, 2, 4)");
    execute("INSERT INTO %s (a, b, c) VALUES (4, 1, 7)");
    // Adds tomstones
    execute("INSERT INTO %s (a, b, c) VALUES (0, 1, 4)");
    execute("INSERT INTO %s (a, b, c) VALUES (5, 2, 7)");
    execute("DELETE FROM %s WHERE a = 0");
    execute("DELETE FROM %s WHERE a = 5");
    beforeAndAfterFlush(() -> {
        // Checks filtering
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE a = 1 AND b = 4 AND c = 4");
        assertRows(execute("SELECT * FROM %s WHERE a = 1 AND b = 2 AND c = 4 ALLOW FILTERING"), row(1, 2, 4));
        assertRows(execute("SELECT * FROM %s WHERE a = 1 AND b = 2 ALLOW FILTERING"), row(1, 2, 4));
        assertRows(execute("SELECT * FROM %s WHERE b >= 2 AND c <= 4 ALLOW FILTERING"), row(1, 2, 4), row(3, 2, 4));
        assertRows(execute("SELECT * FROM %s WHERE a = 1 ALLOW FILTERING"), row(1, 2, 4));
        assertRows(execute("SELECT * FROM %s WHERE b >= 2 ALLOW FILTERING"), row(1, 2, 4), row(3, 2, 4));
        assertRows(execute("SELECT * FROM %s WHERE a >= 2 AND b <=1 ALLOW FILTERING"), row(2, 1, 6), row(4, 1, 7));
        assertRows(execute("SELECT * FROM %s WHERE a = 1 AND c >= 4 ALLOW FILTERING"), row(1, 2, 4));
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE a = 1 AND b IN (1, 2) AND c IN (6, 7)");
        assertRows(execute("SELECT * FROM %s WHERE a IN (1, 2) AND c IN (6, 7) ALLOW FILTERING"), row(2, 1, 6));
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE c > 4");
        assertRows(execute("SELECT * FROM %s WHERE c > 4 ALLOW FILTERING"), row(2, 1, 6), row(4, 1, 7));
        assertRows(execute("SELECT * FROM %s WHERE a >= 1 AND b >= 2 AND c <= 4 ALLOW FILTERING"), row(1, 2, 4), row(3, 2, 4));
        assertRows(execute("SELECT * FROM %s WHERE a < 3 AND c <= 4 ALLOW FILTERING"), row(1, 2, 4));
        assertRows(execute("SELECT * FROM %s WHERE a < 3 AND b >= 2 AND c <= 4 ALLOW FILTERING"), row(1, 2, 4));
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE c >= 3 AND c <= 6");
        assertRows(execute("SELECT * FROM %s WHERE c <=6 ALLOW FILTERING"), row(1, 2, 4), row(2, 1, 6), row(3, 2, 4));
        assertRows(execute("SELECT * FROM %s WHERE token(a) >= token(2)"), row(2, 1, 6), row(4, 1, 7), row(3, 2, 4));
        assertRows(execute("SELECT * FROM %s WHERE token(a) >= token(2) ALLOW FILTERING"), row(2, 1, 6), row(4, 1, 7), row(3, 2, 4));
        assertRows(execute("SELECT * FROM %s WHERE token(a) >= token(2) AND b = 1 ALLOW FILTERING"), row(2, 1, 6), row(4, 1, 7));
    });
}

