@Test
public void filteringOnCompactTable() throws Throwable {
    createTable("CREATE TABLE %s (a int, b int, c int, d int, PRIMARY KEY (a, b, c)) WITH COMPACT STORAGE");
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 11, 12, 13, 14);
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 21, 22, 23, 24);
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 21, 25, 26, 27);
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 31, 32, 33, 34);
    beforeAndAfterFlush(() -> {
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE c > 13"), row(21, 22, 23, 24), row(21, 25, 26, 27), row(31, 32, 33, 34));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE c > 13 AND c < 33"), row(21, 22, 23, 24), row(21, 25, 26, 27));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE c > 13 AND b < 32"), row(21, 22, 23, 24), row(21, 25, 26, 27));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE a = 21 AND c > 13 AND b < 32 ORDER BY b DESC"), row(21, 25, 26, 27), row(21, 22, 23, 24));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE a IN (21, 31) AND c > 13 ORDER BY b DESC"), row(31, 32, 33, 34), row(21, 25, 26, 27), row(21, 22, 23, 24));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE c > 13 AND d < 34"), row(21, 22, 23, 24), row(21, 25, 26, 27));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE c > 13"), row(21, 22, 23, 24), row(21, 25, 26, 27), row(31, 32, 33, 34));
    });
    // with frozen in clustering key
    createTable("CREATE TABLE %s (a int, b int, c frozen<list<int>>, d int, PRIMARY KEY (a, b, c)) WITH COMPACT STORAGE");
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 11, 12, list(1, 3), 14);
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 21, 22, list(2, 3), 24);
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 21, 25, list(2, 6), 27);
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 31, 32, list(3, 3), 34);
    beforeAndAfterFlush(() -> {
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE c CONTAINS 2"), row(21, 22, list(2, 3), 24), row(21, 25, list(2, 6), 27));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE c CONTAINS 2 AND b < 25"), row(21, 22, list(2, 3), 24));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE c CONTAINS 2 AND c CONTAINS 3"), row(21, 22, list(2, 3), 24));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE b > 12 AND c CONTAINS 2 AND d < 27"), row(21, 22, list(2, 3), 24));
    });
    // with frozen in value
    createTable("CREATE TABLE %s (a int, b int, c int, d frozen<list<int>>, PRIMARY KEY (a, b, c)) WITH COMPACT STORAGE");
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 11, 12, 13, list(1, 4));
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 21, 22, 23, list(2, 4));
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 21, 25, 25, list(2, 6));
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 31, 32, 34, list(3, 4));
    beforeAndAfterFlush(() -> {
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE d CONTAINS 2"), row(21, 22, 23, list(2, 4)), row(21, 25, 25, list(2, 6)));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE d CONTAINS 2 AND b < 25"), row(21, 22, 23, list(2, 4)));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE d CONTAINS 2 AND d CONTAINS 4"), row(21, 22, 23, list(2, 4)));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE b > 12 AND c < 25 AND d CONTAINS 2"), row(21, 22, 23, list(2, 4)));
    });
}

@Test
public void testFilteringWithCounters() throws Throwable {
    createTable("CREATE TABLE %s (a int, b int, c int, cnt counter, PRIMARY KEY (a, b, c))" + CompactStorageSplit1Test.compactOption);
    execute("UPDATE %s SET cnt = cnt + ? WHERE a = ? AND b = ? AND c = ?", 14L, 11, 12, 13);
    execute("UPDATE %s SET cnt = cnt + ? WHERE a = ? AND b = ? AND c = ?", 24L, 21, 22, 23);
    execute("UPDATE %s SET cnt = cnt + ? WHERE a = ? AND b = ? AND c = ?", 27L, 21, 25, 26);
    execute("UPDATE %s SET cnt = cnt + ? WHERE a = ? AND b = ? AND c = ?", 34L, 31, 32, 33);
    execute("UPDATE %s SET cnt = cnt + ? WHERE a = ? AND b = ? AND c = ?", 24L, 41, 42, 43);
    beforeAndAfterFlush(() -> {
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE cnt = 24"), row(21, 22, 23, 24L), row(41, 42, 43, 24L));
