    assertRows(execute("UPDATE %s SET l = null WHERE k = 0 IF l IN (?, ?)", null, list("bar")), row(true));
    // Does not apply
    assertRows(execute("UPDATE %s SET l = null WHERE k = 0 IF l = ?", list("bar")), row(false, null));
