    assertRows(execute("UPDATE %s SET s = null WHERE k = 0 IF s = ?", set()), row(true));
    assertRows(execute("UPDATE %s SET s = null WHERE k = 0 IF s != ?", set("bar")), row(true));
    assertRows(execute("UPDATE %s SET s = null WHERE k = 0 IF s < ?", set("a")), row(true));
    assertRows(execute("UPDATE %s SET s = null WHERE k = 0 IF s <= ?", set("a")), row(true));
    assertRows(execute("UPDATE %s SET s = null WHERE k = 0 IF s IN (?, ?)", null, set("bar")), row(true));
    // Does not apply
    assertRows(execute("UPDATE %s SET s = null WHERE k = 0 IF s = ?", set("bar")), row(false, null));
    assertRows(execute("UPDATE %s SET s = null WHERE k = 0 IF s > ?", set("a")), row(false, null));
    assertRows(execute("UPDATE %s SET s = null WHERE k = 0 IF s >= ?", set("a")), row(false, null));
    assertRows(execute("UPDATE %s SET s = null WHERE k = 0 IF s CONTAINS ?", "bar"), row(false, null));
    assertRows(execute("UPDATE %s SET s = null WHERE k = 0 IF s CONTAINS ?", unset()), row(false, null));
    assertInvalidMessage("Invalid comparison with null for operator \"CONTAINS\"", "UPDATE %s SET s = null WHERE k = 0 IF s CONTAINS ?", (ByteBuffer) null);
    createTable("CREATE TABLE %s (k int PRIMARY KEY, m map<text, text>) ");
    execute("INSERT INTO %s (k, m) VALUES (0, null)");
    // Does apply
    assertRows(execute("UPDATE %s SET m = null WHERE k = 0 IF m = ?", (ByteBuffer) null), row(true));
    assertRows(execute("UPDATE %s SET m = null WHERE k = 0 IF m = ?", map()), row(true));
    assertRows(execute("UPDATE %s SET m = null WHERE k = 0 IF m != ?", map("foo", "bar")), row(true));
    assertRows(execute("UPDATE %s SET m = null WHERE k = 0 IF m < ?", map("a", "a")), row(true));
    assertRows(execute("UPDATE %s SET m = null WHERE k = 0 IF m <= ?", map("a", "a")), row(true));
    assertRows(execute("UPDATE %s SET m = null WHERE k = 0 IF m IN (?, ?)", null, map("foo", "bar")), row(true));
    // Does not apply
    assertRows(execute("UPDATE %s SET m = null WHERE k = 0 IF m = ?", map("foo", "bar")), row(false, null));
    assertRows(execute("UPDATE %s SET m = null WHERE k = 0 IF m > ?", map("a", "a")), row(false, null));
    assertRows(execute("UPDATE %s SET m = null WHERE k = 0 IF m >= ?", map("a", "a")), row(false, null));
    assertRows(execute("UPDATE %s SET m = null WHERE k = 0 IF m CONTAINS ?", "bar"), row(false, null));
    assertRows(execute("UPDATE %s SET m = {} WHERE k = 0 IF m CONTAINS ?", unset()), row(false, null));
    assertRows(execute("UPDATE %s SET m = {} WHERE k = 0 IF m CONTAINS KEY ?", "foo"), row(false, null));
    assertRows(execute("UPDATE %s SET m = {} WHERE k = 0 IF m CONTAINS KEY ?", unset()), row(false, null));
    assertInvalidMessage("Invalid comparison with null for operator \"CONTAINS\"", "UPDATE %s SET m = {} WHERE k = 0 IF m CONTAINS ?", (ByteBuffer) null);
