    assertRows(execute("BEGIN BATCH\n" + "INSERT INTO %1$s (a, b, s1, v) values (6, 6, 6, 6);\n" + "DELETE s1 FROM %1$s WHERE a = 6 IF s2 IN (1,2,3);\n" + "APPLY BATCH"), row(false));
