        assertRowsNet(executeNetWithPaging("SELECT DISTINCT a, s, count(a), count(s) FROM %s WHERE a IN (1, 2, 3, 4) GROUP BY a", pageSize), row(1, 1, 1L, 1L), row(2, 2, 1L, 1L), row(3, 3, 1L, 1L), row(4, null, 1L, 0L));
