@Test
public void testFilterWithFunction() throws Throwable {
    createTable("CREATE TABLE %s (a int, b int, c int, PRIMARY KEY (a, b))");
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 0, 0, 0);
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 0, 1, 1);
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 1, 0, 2);
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 1, 1, 3);
    createView("CREATE MATERIALIZED VIEW %s AS SELECT * FROM %s " + "WHERE a = blobAsInt(intAsBlob(1)) AND b IS NOT NULL " + "PRIMARY KEY (a, b)");
    assertRows(executeView("SELECT a, b, c FROM %s"), row(1, 0, 2), row(1, 1, 3));
    executeNet("ALTER TABLE %s RENAME a TO foo");
    assertRows(executeView("SELECT foo, b, c FROM %s"), row(1, 0, 2), row(1, 1, 3));
}

