        execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 1, 1, 1, 0);
        logger.info("Testing MV primary key: {}", mvPrimaryKeys.get(i));
        // only accept rows where b = 1
        createView("CREATE MATERIALIZED VIEW %s AS SELECT * FROM %s " + "WHERE a IS NOT NULL AND b = 1 AND c IS NOT NULL " + "PRIMARY KEY " + mvPrimaryKeys.get(i));
        assertRowsIgnoringOrder(executeView("SELECT a, b, c, d FROM %s"), row(0, 1, 0, 0), row(0, 1, 1, 0), row(1, 1, 0, 0), row(1, 1, 1, 0));
        // insert new rows that do not match the filter
        execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 2, 0, 0, 0);
        execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 2, 2, 0, 0);
        assertRowsIgnoringOrder(executeView("SELECT a, b, c, d FROM %s"), row(0, 1, 0, 0), row(0, 1, 1, 0), row(1, 1, 0, 0), row(1, 1, 1, 0));
        // insert new row that does match the filter
        execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 1, 1, 2, 0);
        assertRowsIgnoringOrder(executeView("SELECT a, b, c, d FROM %s"), row(0, 1, 0, 0), row(0, 1, 1, 0), row(1, 1, 0, 0), row(1, 1, 1, 0), row(1, 1, 2, 0));
