    createTable("CREATE TABLE %s (" + "a int," + "b int," + "c int," + "d int," + "PRIMARY KEY (a, b))");
    executeNet("USE " + keyspace());
    createView("CREATE MATERIALIZED VIEW %s AS SELECT * FROM %s " + "WHERE a IS NOT NULL AND b IS NOT NULL AND d IS NOT NULL " + "PRIMARY KEY (a, d, b)");
