    assertRows(execute("SELECT j, intval FROM " + keyspace() + ".dummy_table WHERE j = ?", 0), row(0, 1));
    assertRows(execute("SELECT k, intval from " + mv + " WHERE intval = ?", 1), row(0, 1));
}

