    assertEmpty(testFunctionInWhereClause("CREATE TABLE %s (k bigint PRIMARY KEY, v int)", null, "CREATE MATERIALIZED VIEW %s AS" + "   SELECT * FROM %s WHERE k = token(1) AND v IS NOT NULL " + "   PRIMARY KEY (v, k)", "k = token(1) AND v IS NOT NULL", "INSERT INTO %s(k, v) VALUES (0, 1)", "INSERT INTO %s(k, v) VALUES (2, 3)"));
    // Native token function with uppercase, should be unquoted and lowercased in the schema where clause
    assertEmpty(testFunctionInWhereClause("CREATE TABLE %s (k bigint PRIMARY KEY, v int)", null, "CREATE MATERIALIZED VIEW %s AS" + "   SELECT * FROM %s WHERE k = TOKEN(1) AND v IS NOT NULL" + "   PRIMARY KEY (v, k)", "k = token(1) AND v IS NOT NULL", "INSERT INTO %s(k, v) VALUES (0, 1)", "INSERT INTO %s(k, v) VALUES (2, 3)"));
    // UDF with lowercase name, shouldn't be quoted in the schema where clause
    assertRows(testFunctionInWhereClause("CREATE TABLE %s (k int PRIMARY KEY, v int)", "CREATE FUNCTION fun()" + "   CALLED ON NULL INPUT" + "   RETURNS int LANGUAGE java" + "   AS 'return 2;'", "CREATE MATERIALIZED VIEW %s AS " + "   SELECT * FROM %s WHERE k = fun() AND v IS NOT NULL" + "   PRIMARY KEY (v, k)", "k = fun() AND v IS NOT NULL", "INSERT INTO %s(k, v) VALUES (0, 1)", "INSERT INTO %s(k, v) VALUES (2, 3)"), row(3, 2));
    // UDF with uppercase name, should be quoted in the schema where clause
    assertRows(testFunctionInWhereClause("CREATE TABLE %s (k int PRIMARY KEY, v int)", "CREATE FUNCTION \"FUN\"()" + "   CALLED ON NULL INPUT" + "   RETURNS int" + "   LANGUAGE java" + "   AS 'return 2;'", "CREATE MATERIALIZED VIEW %s AS " + "   SELECT * FROM %s WHERE k = \"FUN\"() AND v IS NOT NULL" + "   PRIMARY KEY (v, k)", "k = \"FUN\"() AND v IS NOT NULL", "INSERT INTO %s(k, v) VALUES (0, 1)", "INSERT INTO %s(k, v) VALUES (2, 3)"), row(3, 2));
    // UDF with uppercase name conflicting with TOKEN keyword but not with native token function name,
    // should be quoted in the schema where clause
    assertRows(testFunctionInWhereClause("CREATE TABLE %s (k int PRIMARY KEY, v int)", "CREATE FUNCTION \"TOKEN\"(x int)" + "   CALLED ON NULL INPUT" + "   RETURNS int" + "   LANGUAGE java" + "   AS 'return x;'", "CREATE MATERIALIZED VIEW %s AS" + "   SELECT * FROM %s WHERE k = \"TOKEN\"(2) AND v IS NOT NULL" + "   PRIMARY KEY (v, k)", "k = \"TOKEN\"(2) AND v IS NOT NULL", "INSERT INTO %s(k, v) VALUES (0, 1)", "INSERT INTO %s(k, v) VALUES (2, 3)"), row(3, 2));
    // UDF with lowercase name conflicting with both TOKEN keyword and native token function name,
    // requires specifying the keyspace and should be quoted in the schema where clause
    assertRows(testFunctionInWhereClause("CREATE TABLE %s (k int PRIMARY KEY, v int)", "CREATE FUNCTION \"token\"(x int)" + "   CALLED ON NULL INPUT" + "   RETURNS int" + "   LANGUAGE java" + "   AS 'return x;'", "CREATE MATERIALIZED VIEW %s AS" + "   SELECT * FROM %s " + "   WHERE k = " + keyspace() + ".\"token\"(2) AND v IS NOT NULL" + "   PRIMARY KEY (v, k)", "k = " + keyspace() + ".\"token\"(2) AND v IS NOT NULL", "INSERT INTO %s(k, v) VALUES (0, 1)", "INSERT INTO %s(k, v) VALUES (2, 3)"), row(3, 2));
}

/**
 * Tests that truncating a table stops the ongoing builds of its materialized views,
 * so they don't write into the MV data that has been truncated in the base table.
 * <p>
 * See CASSANDRA-16567 for further details.
 */
@Test
@BMRules(rules = { @BMRule(name = "Block view builder tasks", targetClass = "ViewBuilderTask", targetMethod = "buildKey", action = "com.google.common.util.concurrent.Uninterruptibles.awaitUninterruptibly" + "(org.apache.cassandra.cql3.ViewTest.blockViewBuild);"), @BMRule(name = "Unblock view builder tasks", targetClass = "ColumnFamilyStore", targetMethod = "truncateBlocking", action = "org.apache.cassandra.cql3.ViewTest.blockViewBuild.countDown();") })
public void testTruncateWhileBuilding() throws Throwable {
    createTable("CREATE TABLE %s (k int, c int, v int, PRIMARY KEY(k, c))");
    execute("INSERT INTO %s (k, c, v) VALUES (?, ?, ?)", 0, 0, 0);
    createViewAsync("CREATE MATERIALIZED VIEW %s AS SELECT * FROM %s " + "WHERE k IS NOT NULL AND c IS NOT NULL AND v IS NOT NULL " + "PRIMARY KEY (v, c, k)");
    // check that the delayed view builder tasks are either running or pending,
    // and that they haven't written anything yet
    assertThat(runningViewBuilds()).isPositive();
    assertFalse(SystemKeyspace.isViewBuilt(KEYSPACE, currentView()));
    waitForViewMutations();
    assertRows(executeView("SELECT * FROM %s"));
    // truncate the view, this should unblock the view builders, wait for their cancellation,
    // drop the sstables and, finally, start a new view build
    updateView("TRUNCATE %s");
    // check that there aren't any rows after truncating
    assertRows(executeView("SELECT * FROM %s"));
    // check that the view builder tasks finish and that the view is still empty after that
    Awaitility.await().untilAsserted(() -> assertEquals(0, runningViewBuilds()));
    assertTrue(SystemKeyspace.isViewBuilt(KEYSPACE, currentView()));
    waitForViewMutations();
    assertRows(executeView("SELECT * FROM %s"));
}

@Test
public void testRegularColumnTimestampUpdates() throws Throwable {
    // Regression test for CASSANDRA-10910
    createTable("CREATE TABLE %s (" + "k int PRIMARY KEY, " + "c int, " + "val int)");
    createView("CREATE MATERIALIZED VIEW %s AS SELECT * FROM %s " + "WHERE k IS NOT NULL AND c IS NOT NULL " + "PRIMARY KEY (k,c)");
    updateView("UPDATE %s SET c = ?, val = ? WHERE k = ?", 0, 0, 0);
    updateView("UPDATE %s SET val = ? WHERE k = ?", 1, 0);
    updateView("UPDATE %s SET c = ? WHERE k = ?", 1, 0);
    assertRows(executeView("SELECT c, k, val FROM %s"), row(1, 0, 1));
    updateView("TRUNCATE %s");
    updateView("UPDATE %s USING TIMESTAMP 1 SET c = ?, val = ? WHERE k = ?", 0, 0, 0);
    updateView("UPDATE %s USING TIMESTAMP 3 SET c = ? WHERE k = ?", 1, 0);
    updateView("UPDATE %s USING TIMESTAMP 2 SET val = ? WHERE k = ?", 1, 0);
    updateView("UPDATE %s USING TIMESTAMP 4 SET c = ? WHERE k = ?", 2, 0);
    updateView("UPDATE %s USING TIMESTAMP 3 SET val = ? WHERE k = ?", 2, 0);
    assertRows(executeView("SELECT c, k, val FROM %s"), row(2, 0, 2));
    assertRows(executeView("SELECT c, k, val FROM %s limit 1"), row(2, 0, 2));
}

