    test("SELECT * FROM %s WHERE v2 > 2 ALLOW FILTERING");
    test("SELECT * FROM %s WHERE k1 = 1 AND v1 = 1 ALLOW FILTERING");
    test("SELECT * FROM %s WHERE k1 = 1 AND v2 = 1 ALLOW FILTERING");
    test("SELECT * FROM %s WHERE k2 = 2 AND v1 = 1 ALLOW FILTERING");
    test("SELECT * FROM %s WHERE k2 = 2 AND v2 = 1 ALLOW FILTERING");
    test("SELECT * FROM %s WHERE v1 = 1 AND v2 = 2 ALLOW FILTERING");
    test("SELECT * FROM %s WHERE token(k1, k2) > 0 AND k1 = 1");
    test("SELECT * FROM %s WHERE token(k1, k2) > 0 AND k2 = 2");
    test("SELECT * FROM %s WHERE token(k1, k2) > 0 AND v1 = 1");
    test("SELECT * FROM %s WHERE token(k1, k2) > 0 AND v2 = 2");
    test("SELECT * FROM %s WHERE k1 = 1 AND k2 = 2 AND v1 = 1", "SELECT * FROM %s WHERE token(k1, k2) >= token(1, 2) AND token(k1, k2) <= token(1, 2) AND v1 = 1");
    // grouped partition-directed queries, maybe producing multiple queries
    test("SELECT * FROM %s WHERE k1 IN (1) AND k2 = 2", "SELECT * FROM %s WHERE k1 = 1 AND k2 = 2");
    test("SELECT * FROM %s WHERE k1 = 1 AND k2 IN (2)", "SELECT * FROM %s WHERE k1 = 1 AND k2 = 2");
    test("SELECT * FROM %s WHERE k1 IN (1) AND k2 IN (2)", "SELECT * FROM %s WHERE k1 = 1 AND k2 = 2");
    test("SELECT * FROM %s WHERE k1 IN (0, 1) AND k2 = 2", "SELECT * FROM %s WHERE k1 = 0 AND k2 = 2", "SELECT * FROM %s WHERE k1 = 1 AND k2 = 2");
    test("SELECT * FROM %s WHERE k1 = 1 AND k2 IN (2, 3)", "SELECT * FROM %s WHERE k1 = 1 AND k2 = 2", "SELECT * FROM %s WHERE k1 = 1 AND k2 = 3");
    test("SELECT * FROM %s WHERE k1 IN (0, 1) AND k2 IN (2, 3)", "SELECT * FROM %s WHERE k1 = 0 AND k2 = 2", "SELECT * FROM %s WHERE k1 = 0 AND k2 = 3", "SELECT * FROM %s WHERE k1 = 1 AND k2 = 2", "SELECT * FROM %s WHERE k1 = 1 AND k2 = 3");
}

