    test("SELECT * FROM %s WHERE k = 0 AND v1 = 1", "SELECT * FROM %s WHERE token(k) >= token(0) AND token(k) <= token(0) AND v1 = 1");
    test("SELECT * FROM %s WHERE k = 0 AND v1 = 1 AND c = 1", "SELECT * FROM %s WHERE token(k) >= token(0) AND token(k) <= token(0) AND c = 1 AND v1 = 1 ALLOW FILTERING");
    // grouped partition-directed queries, maybe producing multiple queries
    test("SELECT * FROM %s WHERE k IN (0)", "SELECT * FROM %s WHERE k = 0");
    test("SELECT * FROM %s WHERE k IN (0, 1)", "SELECT * FROM %s WHERE k = 0", "SELECT * FROM %s WHERE k = 1");
    test("SELECT * FROM %s WHERE k IN (0, 1) AND c = 0", "SELECT * FROM %s WHERE k = 0 AND c = 0", "SELECT * FROM %s WHERE k = 1 AND c = 0");
    test("SELECT * FROM %s WHERE k IN (0, 1) AND c > 0", "SELECT * FROM %s WHERE k = 0 AND c > 0", "SELECT * FROM %s WHERE k = 1 AND c > 0");
    // order by
    test("SELECT * FROM %s WHERE k = 0 ORDER BY c", "SELECT * FROM %s WHERE k = 0");
    test("SELECT * FROM %s WHERE k = 0 ORDER BY c ASC", "SELECT * FROM %s WHERE k = 0");
    test("SELECT * FROM %s WHERE k = 0 ORDER BY c DESC");
