    SyncRunnable syncRunnable = new FakeCommitLogService(syncTimeMillis).new SyncRunnable(new FreeRunningClock());
    long pollStarted = 1;
    long now = pollStarted + (syncTimeMillis - 1);
    int runCount = 12;
    for (int i = 1; i <= runCount; i++) {
