        CompactionIterator iter = new CompactionIterator(OperationType.COMPACTION, Lists.transform(content, x -> new Scanner(x)), controller, NOW, null)) {
        assertTrue(iter.hasNext());
        UnfilteredRowIterator rows = iter.next();
        assertTrue(rows.hasNext());
        assertNotNull(rows.next());
        iter.stop();
        try {
            // Will call Transformation#applyToRow
            rows.hasNext();
            fail("Should have thrown CompactionInterruptedException");
        } catch (CompactionInterruptedException e) {
            // ignore
        }
    }
}

