@Test
public void testCompoundType() {
    CompositeType baseType = CompositeType.getInstance(AsciiType.instance, UUIDType.instance, LongType.instance);
    ByteBuffer a1 = CompositeType.build(ByteBufferAccessor.instance, ByteBufferUtil.bytes("a"), UUIDType.instance.fromString("00000000-0000-0000-0000-000000000000"), ByteBufferUtil.bytes(1));
    ByteBuffer a2 = CompositeType.build(ByteBufferAccessor.instance, ByteBufferUtil.bytes("a"), UUIDType.instance.fromString("00000000-0000-0000-0000-000000000000"), ByteBufferUtil.bytes(100));
    ByteBuffer b1 = CompositeType.build(ByteBufferAccessor.instance, ByteBufferUtil.bytes("a"), UUIDType.instance.fromString("ffffffff-ffff-ffff-ffff-ffffffffffff"), ByteBufferUtil.bytes(1));
    ByteBuffer b2 = CompositeType.build(ByteBufferAccessor.instance, ByteBufferUtil.bytes("a"), UUIDType.instance.fromString("ffffffff-ffff-ffff-ffff-ffffffffffff"), ByteBufferUtil.bytes(100));
    ByteBuffer c1 = CompositeType.build(ByteBufferAccessor.instance, ByteBufferUtil.bytes("z"), UUIDType.instance.fromString("00000000-0000-0000-0000-000000000000"), ByteBufferUtil.bytes(1));
    ByteBuffer c2 = CompositeType.build(ByteBufferAccessor.instance, ByteBufferUtil.bytes("z"), UUIDType.instance.fromString("00000000-0000-0000-0000-000000000000"), ByteBufferUtil.bytes(100));
    ByteBuffer d1 = CompositeType.build(ByteBufferAccessor.instance, ByteBufferUtil.bytes("z"), UUIDType.instance.fromString("ffffffff-ffff-ffff-ffff-ffffffffffff"), ByteBufferUtil.bytes(1));
    ByteBuffer d2 = CompositeType.build(ByteBufferAccessor.instance, ByteBufferUtil.bytes("z"), UUIDType.instance.fromString("ffffffff-ffff-ffff-ffff-ffffffffffff"), ByteBufferUtil.bytes(100));
    ByteBuffer z1 = CompositeType.build(ByteBufferAccessor.instance, ByteBufferUtil.EMPTY_BYTE_BUFFER, UUIDType.instance.fromString("ffffffff-ffff-ffff-ffff-ffffffffffff"), ByteBufferUtil.bytes(100));
    assert baseType.compare(a1, a2) < 0;
    assert baseType.compare(a2, b1) < 0;
    assert baseType.compare(b1, b2) < 0;
    assert baseType.compare(b2, c1) < 0;
    assert baseType.compare(c1, c2) < 0;
    assert baseType.compare(c2, d1) < 0;
    assert baseType.compare(d1, d2) < 0;
    assert baseType.compare(a2, a1) > 0;
    assert baseType.compare(b1, a2) > 0;
    assert baseType.compare(b2, b1) > 0;
    assert baseType.compare(c1, b2) > 0;
    assert baseType.compare(c2, c1) > 0;
    assert baseType.compare(d1, c2) > 0;
    assert baseType.compare(d2, d1) > 0;
    assert baseType.compare(z1, a1) < 0;
    assert baseType.compare(z1, a2) < 0;
    assert baseType.compare(z1, b1) < 0;
    assert baseType.compare(z1, b2) < 0;
    assert baseType.compare(z1, c1) < 0;
    assert baseType.compare(z1, c2) < 0;
    assert baseType.compare(z1, d1) < 0;
    assert baseType.compare(z1, d2) < 0;
    assert baseType.compare(a1, a1) == 0;
    assert baseType.compare(a2, a2) == 0;
    assert baseType.compare(b1, b1) == 0;
    assert baseType.compare(b2, b2) == 0;
    assert baseType.compare(c1, c1) == 0;
    assert baseType.compare(c2, c2) == 0;
    assert baseType.compare(z1, z1) == 0;
}

