    // 5G are used of 10G
    guardrails().setDataDiskUsageMaxDiskSize("10GiB");
    assertThat(monitor.getDiskUsage()).isEqualTo(0.5);
    // max disk size = space used
    guardrails().setDataDiskUsageMaxDiskSize("5GiB");
