@Test
public void testValuesWarned() throws Throwable {
    // Using a sorted set below to ensure the order in the warning message checked below is not random
    Values<Integer> warned = new Values<>("x", REASON, state -> insertionOrderedSet(4, 6, 20), state -> Collections.emptySet(), state -> Collections.emptySet(), "integer");
    Consumer<Integer> action = i -> Assert.fail("The ignore action shouldn't have been triggered");
    assertValid(() -> warned.guard(set(3), action, userClientState));
    assertWarns(() -> warned.guard(set(4), action, userClientState), "Provided values [4] are not recommended for integer (warned values are: [4, 6, 20])");
    assertWarns(() -> warned.guard(set(4, 6), action, null), "Provided values [4, 6] are not recommended for integer (warned values are: [4, 6, 20])");
