        RangeTombstoneList l1Initial = l1.copy();
        try {
            // We generate the list randomly, so "all" we check is that the resulting range tombstone list looks valid.
            l1.addAll(l2);
            assertValid(l1);
        } catch (Throwable e) {
            System.out.println("Error merging:");
