    assertRows(UnfilteredRowIterators.concat(iter1, EmptyIterators.unfilteredRow(metadata, dk(1), false, Rows.EMPTY_STATIC_ROW, DeletionTime.LIVE)), row(1, cell(v1Metadata, 1), cell(v2Metadata, 1)), row(2, cell(v1Metadata, 2), cell(v2Metadata, 2)));
    // concat with LHS empty iterator
    iter1 = rows(metadata.regularAndStaticColumns(), 1, row(1, cell(v1Metadata, 1), cell(v2Metadata, 1)), row(2, cell(v1Metadata, 2), cell(v2Metadata, 2)));
    Assert.assertEquals(concat.columns(), metadata.regularAndStaticColumns());
    assertRows(UnfilteredRowIterators.concat(EmptyIterators.unfilteredRow(metadata, dk(1), false, Rows.EMPTY_STATIC_ROW, DeletionTime.LIVE), iter1), row(1, cell(v1Metadata, 1), cell(v2Metadata, 1)), row(2, cell(v1Metadata, 2), cell(v2Metadata, 2)));
    // concat with different columns
    iter1 = rows(metadata.regularAndStaticColumns().without(v1Metadata), 1, row(1, cell(v2Metadata, 1)), row(2, cell(v2Metadata, 2)));
    iter2 = rows(metadata.regularAndStaticColumns().without(v2Metadata), 1, row(3, cell(v1Metadata, 3)), row(4, cell(v1Metadata, 4)));
    concat = UnfilteredRowIterators.concat(iter1, iter2);
    Assert.assertEquals(concat.columns(), RegularAndStaticColumns.of(v1Metadata).mergeTo(RegularAndStaticColumns.of(v2Metadata)));
    assertRows(concat, row(1, cell(v2Metadata, 1)), row(2, cell(v2Metadata, 2)), row(3, cell(v1Metadata, 3)), row(4, cell(v1Metadata, 4)));
    // concat with CQL limits
