    // concat concatenated iterators
    iter1 = rows(metadata.regularAndStaticColumns(), 1, row(1, cell(v1Metadata, 1), cell(v2Metadata, 1)), row(2, cell(v1Metadata, 2), cell(v2Metadata, 2)));
    iter2 = rows(metadata.regularAndStaticColumns(), 1, row(3, cell(v1Metadata, 3), cell(v2Metadata, 3)), row(4, cell(v1Metadata, 4), cell(v2Metadata, 4)));
