@BMRule(name = "Greatest name in the world", targetClass = "HintsBufferPool", targetMethod = "switchCurrentBuffer", targetLocation = "AT INVOKE java.util.concurrent.BlockingQueue.take", action = "org.apache.cassandra.hints.HintsBufferPoolTest.blockedOnBackpressure = true;")
public void testBackpressure() throws Exception {
    Queue<HintsBuffer> returnedBuffers = new ConcurrentLinkedQueue<>();
    HintsBufferPool pool = new HintsBufferPool(256, (buffer, p) -> returnedBuffers.offer(buffer));
