@Test
public void indexBatchStatements() throws Throwable {
    // see CASSANDRA-10536
    createTable("CREATE TABLE %s (a int, b int, c int, PRIMARY KEY (a, b))");
    createIndex("CREATE INDEX ON %s(c)");
    // Multi partition batch
    execute("BEGIN BATCH\n" + "UPDATE %1$s SET c = 0 WHERE a = 0 AND b = 0;\n" + "UPDATE %1$s SET c = 1 WHERE a = 1 AND b = 1;\n" + "APPLY BATCH");
    assertRows(execute("SELECT * FROM %s WHERE c = 0"), row(0, 0, 0));
    assertRows(execute("SELECT * FROM %s WHERE c = 1"), row(1, 1, 1));
    // Single Partition batch
    execute("BEGIN BATCH\n" + "UPDATE %1$s SET c = 2 WHERE a = 2 AND b = 0;\n" + "UPDATE %1$s SET c = 3 WHERE a = 2 AND b = 1;\n" + "APPLY BATCH");
    assertRows(execute("SELECT * FROM %s WHERE c = 2"), row(2, 0, 2));
    assertRows(execute("SELECT * FROM %s WHERE c = 3"), row(2, 1, 3));
}

@Test
public void indexStatementsWithConditions() throws Throwable {
    // see CASSANDRA-10536
    createTable("CREATE TABLE %s (a int, b int, c int, PRIMARY KEY (a, b))");
    createIndex("CREATE INDEX ON %s(c)");
    execute("INSERT INTO %s (a, b, c) VALUES (0, 0, 0) IF NOT EXISTS");
    assertRows(execute("SELECT * FROM %s WHERE c = 0"), row(0, 0, 0));
    execute("INSERT INTO %s (a, b, c) VALUES (0, 0, 1) IF NOT EXISTS");
    assertEmpty(execute("SELECT * FROM %s WHERE c = 1"));
    execute("UPDATE %s SET c = 1 WHERE a = 0 AND b =0 IF c = 0");
    assertRows(execute("SELECT * FROM %s WHERE c = 1"), row(0, 0, 1));
    assertEmpty(execute("SELECT * FROM %s WHERE c = 0"));
    execute("DELETE FROM %s WHERE a = 0 AND b = 0 IF c = 0");
    assertRows(execute("SELECT * FROM %s WHERE c = 1"), row(0, 0, 1));
    execute("DELETE FROM %s WHERE a = 0 AND b = 0 IF c = 1");
    assertEmpty(execute("SELECT * FROM %s WHERE c = 1"));
    execute("BEGIN BATCH\n" + "INSERT INTO %1$s (a, b, c) VALUES (2, 2, 2) IF NOT EXISTS;\n" + "INSERT INTO %1$s (a, b, c) VALUES (2, 3, 3)\n" + "APPLY BATCH");
    assertRows(execute("SELECT * FROM %s WHERE c = 2"), row(2, 2, 2));
    assertRows(execute("SELECT * FROM %s WHERE c = 3"), row(2, 3, 3));
}

@Test
public void indexCorrectlyMarkedAsBuildAndRemoved() throws Throwable {
    String selectBuiltIndexesQuery = String.format("SELECT * FROM %s.\"%s\"", SchemaConstants.SYSTEM_KEYSPACE_NAME, SystemKeyspace.BUILT_INDEXES);
    // Wait for any background index clearing tasks to complete. Warn: When we used to run tests in parallel there
    // could also be cross test class talk and have other indices pop up here.
    Awaitility.await().atMost(1, TimeUnit.MINUTES).pollDelay(1, TimeUnit.SECONDS).untilAsserted(() -> assertRows(execute(selectBuiltIndexesQuery), row("system", "PaxosUncommittedIndex", null)));
    String indexName = "build_remove_test_idx";
    String tableName = createTable("CREATE TABLE %s (a int, b int, c int, PRIMARY KEY (a, b))");
    createIndex(String.format("CREATE INDEX %s ON %%s(c)", indexName));
    waitForIndex(KEYSPACE, tableName, indexName);
    // check that there are no other rows in the built indexes table
    assertRows(execute(selectBuiltIndexesQuery), row(KEYSPACE, indexName, null), row("system", "PaxosUncommittedIndex", null));
    // rebuild the index and verify the built status table
    getCurrentColumnFamilyStore().rebuildSecondaryIndex(indexName);
    waitForIndex(KEYSPACE, tableName, indexName);
    // check that there are no other rows in the built indexes table
    assertRows(execute(selectBuiltIndexesQuery), row(KEYSPACE, indexName, null), row("system", "PaxosUncommittedIndex", null));
    // check that dropping the index removes it from the built indexes table
    dropIndex("DROP INDEX %s." + indexName);
    assertRows(execute(selectBuiltIndexesQuery), row("system", "PaxosUncommittedIndex", null));
}

@Test
public void caseSensitiveAnalizer() throws Exception {
    DelimiterAnalyzer analyzer = new DelimiterAnalyzer();
    analyzer.init(new HashMap() {

        {
            put(DelimiterTokenizingOptions.DELIMITER, " ");
        }
    }, UTF8Type.instance);
    String testString = "Nip it in the bud";
    ByteBuffer toAnalyze = ByteBuffer.wrap(testString.getBytes());
    analyzer.reset(toAnalyze);
    StringBuilder output = new StringBuilder();
    while (analyzer.hasNext()) output.append(ByteBufferUtil.string(analyzer.next()) + (analyzer.hasNext() ? ' ' : ""));
    Assert.assertEquals(testString, output.toString());
    Assert.assertFalse(testString.toLowerCase().equals(output.toString()));
}

