        LZ4Compressor compressor = (LZ4Compressor) sstable.getCompressionMetadata().parameters.getSstableCompressor();
        assertEquals(LZ4Compressor.LZ4_HIGH_COMPRESSOR, compressor.compressorType);
    });
}

