 */
@Ignore
@Test
public void testGenerateSstables() throws Throwable {
    Random rand = new Random();
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < 128; i++) {
        sb.append((char) ('a' + rand.nextInt(26)));
    }
    String randomString = sb.toString();
    for (int pk = 0; pk < 5; pk++) {
        String valPk = Integer.toString(pk);
        QueryProcessor.executeInternal(String.format("INSERT INTO legacy_tables.legacy_%s_simple (pk, val) VALUES ('%s', '%s')", BigFormat.latestVersion, valPk, "foo bar baz"));
        QueryProcessor.executeInternal(String.format("UPDATE legacy_tables.legacy_%s_simple_counter SET val = val + 1 WHERE pk = '%s'", BigFormat.latestVersion, valPk));
        for (int ck = 0; ck < 50; ck++) {
            String valCk = Integer.toString(ck);
            QueryProcessor.executeInternal(String.format("INSERT INTO legacy_tables.legacy_%s_clust (pk, ck, val) VALUES ('%s', '%s', '%s')", BigFormat.latestVersion, valPk, valCk + longString, randomString));
            QueryProcessor.executeInternal(String.format("UPDATE legacy_tables.legacy_%s_clust_counter SET val = val + 1 WHERE pk = '%s' AND ck='%s'", BigFormat.latestVersion, valPk, valCk + longString));
        }
    }
    StorageService.instance.forceKeyspaceFlush("legacy_tables", ColumnFamilyStore.FlushReason.UNIT_TESTS);
    File ksDir = new File(LEGACY_SSTABLE_ROOT, String.format("%s/legacy_tables", BigFormat.latestVersion));
    ksDir.tryCreateDirectories();
    copySstablesFromTestData(String.format("legacy_%s_simple", BigFormat.latestVersion), ksDir);
    copySstablesFromTestData(String.format("legacy_%s_simple_counter", BigFormat.latestVersion), ksDir);
    copySstablesFromTestData(String.format("legacy_%s_clust", BigFormat.latestVersion), ksDir);
    copySstablesFromTestData(String.format("legacy_%s_clust_counter", BigFormat.latestVersion), ksDir);
}

@Test
public void testSerialization() throws IOException {
    Map<MetadataType, MetadataComponent> originalMetadata = constructMetadata();
    MetadataSerializer serializer = new MetadataSerializer();
    File statsFile = serialize(originalMetadata, serializer, BigFormat.latestVersion);
    Descriptor desc = new Descriptor(statsFile.parent(), "", "", new SequenceBasedSSTableId(0), SSTableFormat.Type.BIG);
    try (RandomAccessReader in = RandomAccessReader.open(statsFile)) {
        Map<MetadataType, MetadataComponent> deserialized = serializer.deserialize(desc, in, EnumSet.allOf(MetadataType.class));
        for (MetadataType type : MetadataType.values()) {
            assertEquals(originalMetadata.get(type), deserialized.get(type));
        }
    }
}

@Test
public void testHistogramSterilization() throws IOException {
    Map<MetadataType, MetadataComponent> originalMetadata = constructMetadata();
    // Modify the histograms to overflow:
    StatsMetadata originalStats = (StatsMetadata) originalMetadata.get(MetadataType.STATS);
    originalStats.estimatedCellPerPartitionCount.add(Long.MAX_VALUE);
    originalStats.estimatedPartitionSize.add(Long.MAX_VALUE);
    assertTrue(originalStats.estimatedCellPerPartitionCount.isOverflowed());
    assertTrue(originalStats.estimatedPartitionSize.isOverflowed());
    // Serialize w/ overflowed histograms:
    MetadataSerializer serializer = new MetadataSerializer();
    File statsFile = serialize(originalMetadata, serializer, BigFormat.latestVersion);
    Descriptor desc = new Descriptor(statsFile.parent(), "", "", new SequenceBasedSSTableId(0), SSTableFormat.Type.BIG);
    try (RandomAccessReader in = RandomAccessReader.open(statsFile)) {
        // Deserialie and verify that the two histograms have had their overflow buckets cleared:
        Map<MetadataType, MetadataComponent> deserialized = serializer.deserialize(desc, in, EnumSet.allOf(MetadataType.class));
        StatsMetadata deserializedStats = (StatsMetadata) deserialized.get(MetadataType.STATS);
        assertFalse(deserializedStats.estimatedCellPerPartitionCount.isOverflowed());
        assertFalse(deserializedStats.estimatedPartitionSize.isOverflowed());
    }
}

