@Test
public void testComparator() {
    List<SSTableId> ids = new ArrayList<>(Collections.nCopies(300, null));
    for (int i = 0; i < 100; i++) {
        ids.set(i + 100, new SequenceBasedSSTableId(ThreadLocalRandom.current().nextInt(1000000)));
        ids.set(i, new UUIDBasedSSTableId(TimeUUID.Generator.atUnixMillis(ThreadLocalRandom.current().nextLong(10000), 0)));
    }
    List<SSTableId> shuffledIds = new ArrayList<>(ids);
    Collections.shuffle(shuffledIds);
    assertThat(shuffledIds).isNotEqualTo(ids);
    List<SSTableId> sortedIds = new ArrayList<>(shuffledIds);
    sortedIds.sort(SSTableIdFactory.COMPARATOR);
    assertThat(sortedIds).isNotEqualTo(shuffledIds);
    assertThat(sortedIds).isSortedAccordingTo(SSTableIdFactory.COMPARATOR);
    assertThat(sortedIds.subList(0, 100)).containsOnlyNulls();
    assertThat(sortedIds.subList(100, 200)).allMatch(id -> id instanceof SequenceBasedSSTableId);
    assertThat(sortedIds.subList(200, 300)).allMatch(id -> id instanceof UUIDBasedSSTableId);
    assertThat(sortedIds.subList(100, 200)).isSortedAccordingTo(Comparator.comparing(o -> ((SequenceBasedSSTableId) o)));
    assertThat(sortedIds.subList(200, 300)).isSortedAccordingTo(Comparator.comparing(o -> ((UUIDBasedSSTableId) o)));
}

@Test
public void testLoadingSSTable() throws Exception {
    File dataDir = dataDir(CF_STANDARD1);
    TableMetadata metadata = Schema.instance.getTableMetadata(KEYSPACE1, CF_STANDARD1);
    try (CQLSSTableWriter writer = CQLSSTableWriter.builder().inDirectory(dataDir).forTable(String.format(schema, KEYSPACE1, CF_STANDARD1)).using(String.format(query, KEYSPACE1, CF_STANDARD1)).build()) {
        writer.addRow("key1", "col1", "100");
    }
    ColumnFamilyStore cfs = Keyspace.open(KEYSPACE1).getColumnFamilyStore(CF_STANDARD1);
    // wait for sstables to be on disk else we won't be able to stream them
    Util.flush(cfs);
    final CountDownLatch latch = new CountDownLatch(1);
    SSTableLoader loader = new SSTableLoader(dataDir, new TestClient(), new OutputHandler.SystemOutput(false, false));
    loader.stream(Collections.emptySet(), completionStreamListener(latch)).get();
    List<FilteredPartition> partitions = Util.getAll(Util.cmd(cfs).build());
    assertEquals(1, partitions.size());
    assertEquals("key1", AsciiType.instance.getString(partitions.get(0).partitionKey().getKey()));
    assert metadata != null;
    Row row = partitions.get(0).getRow(Clustering.make(ByteBufferUtil.bytes("col1")));
    assert row != null;
    assertEquals(ByteBufferUtil.bytes("100"), row.getCell(metadata.getColumn(ByteBufferUtil.bytes("val"))).buffer());
    // The stream future is signalled when the work is complete but before releasing references. Wait for release
    // before cleanup (CASSANDRA-10118).
    latch.await();
}

@Test
public void testLoadingIncompleteSSTable() throws Exception {
    File dataDir = dataDir(CF_STANDARD2);
    CQLSSTableWriter writer = CQLSSTableWriter.builder().inDirectory(dataDir).forTable(String.format(schema, KEYSPACE1, CF_STANDARD2)).using(String.format(query, KEYSPACE1, CF_STANDARD2)).withBufferSizeInMiB(1).build();
    // Enough to write >1MiB and get at least one completed sstable before we've closed the writer
    int NB_PARTITIONS = 5000;
    for (int i = 0; i < NB_PARTITIONS; i++) {
        for (int j = 0; j < 100; j++) writer.addRow(String.format("key%d", i), String.format("col%d", j), "100");
    }
    ColumnFamilyStore cfs = Keyspace.open(KEYSPACE1).getColumnFamilyStore(CF_STANDARD2);
    // wait for sstables to be on disk else we won't be able to stream them
    Util.flush(cfs);
    //make sure we have some tables...
    assertTrue(Objects.requireNonNull(dataDir.tryList()).length > 0);
    final CountDownLatch latch = new CountDownLatch(2);
    //writer is still open so loader should not load anything
    SSTableLoader loader = new SSTableLoader(dataDir, new TestClient(), new OutputHandler.SystemOutput(false, false));
    loader.stream(Collections.emptySet(), completionStreamListener(latch)).get();
    List<FilteredPartition> partitions = Util.getAll(Util.cmd(cfs).build());
    assertTrue(partitions.size() > 0 && partitions.size() < NB_PARTITIONS);
    // now we complete the write and the second loader should load the last sstable as well
    writer.close();
    loader = new SSTableLoader(dataDir, new TestClient(), new OutputHandler.SystemOutput(false, false));
    loader.stream(Collections.emptySet(), completionStreamListener(latch)).get();
    partitions = Util.getAll(Util.cmd(Keyspace.open(KEYSPACE1).getColumnFamilyStore(CF_STANDARD2)).build());
    assertEquals(NB_PARTITIONS, partitions.size());
    // The stream future is signalled when the work is complete but before releasing references. Wait for release
    // before cleanup (CASSANDRA-10118).
    latch.await();
}

