@Test
public void serializeSizeProperty() {
    try (DataOutputBuffer out = new DataOutputBuffer(1024)) {
        qt().forAll(MESSAGE_GEN).checkAssert(orFail(message -> {
            for (MessagingService.Version version : MessagingService.Version.values()) {
                out.clear();
                serializer.serialize(message, out, version.value);
                Assertions.assertThat(out.getLength()).as("Property serialize(out, version).length == serializedSize(version) " + "was violated for version %s and verb %s", version, message.header.verb).isEqualTo(message.serializedSize(version.value));
