    Assert.assertEquals(h(pt(10, none()), pt(20, 6), pt(30, 5)), builder.add(b(6), r(10, 20)).add(b(5), r(15, 30)).history);
    builder.clear();
    Assert.assertEquals(h(pt(10, none()), pt(20, 5), pt(30, 6)), builder.add(b(5), r(10, 25)).add(b(6), r(20, 30)).history);
