@Test
public void testStartAndStopScheduledSampling() {
    List<String> allSamplers = Arrays.stream(Sampler.SamplerType.values()).map(Enum::toString).collect(Collectors.toList());
    StorageService ss = StorageService.instance;
    assertTrue("Scheduling new sampled tasks should be allowed", ss.startSamplingPartitions(null, null, 10, 10, 100, 10, allSamplers));
    assertEquals(Collections.singletonList("*.*"), ss.getSampleTasks());
    assertFalse("Sampling with duplicate keys should be disallowed", ss.startSamplingPartitions(null, null, 20, 20, 100, 10, allSamplers));
    assertTrue("Existing scheduled sampling tasks should be cancellable", ss.stopSamplingPartitions(null, null));
    int timeout = 10;
    while (timeout-- > 0 && ss.getSampleTasks().size() > 0) Uninterruptibles.sleepUninterruptibly(10, TimeUnit.MILLISECONDS);
    assertEquals("Scheduled sampled tasks should be removed", Collections.emptyList(), ss.getSampleTasks());
    assertTrue("When nothing is scheduled, you should be able to stop all scheduled sampling tasks", ss.stopSamplingPartitions(null, null));
}

