    m = e.toMap();
    assertEquals("testuser", m.get("user"));
    assertEquals(spStmt, m.get("operation"));
    assertEquals("testks", m.get("keyspace"));
    assertEquals("table1", m.get("scope"));
    assertEquals(AuditLogEntryType.UPDATE, e.getType());
}

