@Test
public void testDecimalType() {
    // We won't be using testValuesForType for DecimalType (i.e. we won't also be comparing the initial and decoded
    // ByteBuffer values). That's because the same BigDecimal value can be represented with a couple of different,
    // even if equivalent pairs of <mantissa, scale> (e.g. 0.1 is 1 * e-1, as well as 10 * e-2, as well as...).
    // And in practice it's easier to just convert to BigDecimals and then compare, instead of trying to manually
    // decode and convert to canonical representations, which then to compare. For example of generating canonical
    // decimals in the first place, see testReversedType().
    Consumer<BigDecimal> bigDecimalConsumer = initial -> {
        ByteSource byteSource = DecimalType.instance.asComparableBytes(DecimalType.instance.decompose(initial), version);
        BigDecimal decoded = DecimalType.instance.compose(DecimalType.instance.fromComparableBytes(ByteSource.peekable(byteSource), version));
        if (initial == null)
            Assert.assertNull(decoded);
        else
            Assert.assertEquals(0, initial.compareTo(decoded));
    };
    // Test some interesting predefined BigDecimal values.
    Stream.of(null, BigDecimal.ZERO, BigDecimal.ONE, BigDecimal.ONE.add(BigDecimal.ONE), BigDecimal.TEN, BigDecimal.valueOf(0.0000000000000000000000000000000001), BigDecimal.valueOf(-0.0000000000000000000000000000000001), BigDecimal.valueOf(0.0000000000000001234567891011121314), BigDecimal.valueOf(-0.0000000000000001234567891011121314), BigDecimal.valueOf(12345678910111213.141516171819202122), BigDecimal.valueOf(-12345678910111213.141516171819202122), new BigDecimal(BigInteger.TEN, Integer.MIN_VALUE), new BigDecimal(BigInteger.TEN.negate(), Integer.MIN_VALUE), new BigDecimal(BigInteger.TEN, Integer.MAX_VALUE), new BigDecimal(BigInteger.TEN.negate(), Integer.MAX_VALUE), new BigDecimal(BigInteger.TEN.pow(1000), Integer.MIN_VALUE), new BigDecimal(BigInteger.TEN.pow(1000).negate(), Integer.MIN_VALUE), new BigDecimal(BigInteger.TEN.pow(1000), Integer.MAX_VALUE), new BigDecimal(BigInteger.TEN.pow(1000).negate(), Integer.MAX_VALUE)).forEach(bigDecimalConsumer);
    // Test BigDecimals created from random double values with predefined range modifiers.
    double[] bounds = { Double.MIN_VALUE, -1_000_000_000.0, -100_000.0, -1.0, 1.0, 100_000.0, 1_000_000_000.0, Double.MAX_VALUE };
    for (double bound : bounds) {
        new Random().doubles(1000).mapToObj(initial -> BigDecimal.valueOf(initial * bound)).forEach(bigDecimalConsumer);
    }
}

