    ByteBuffer vOne = TupleType.buildValue(ByteBufferAccessor.instance, decomposeAndRandomPad(UTF8Type.instance, "str"));
    ByteBuffer vOneAndNull = TupleType.buildValue(ByteBufferAccessor.instance, decomposeAndRandomPad(UTF8Type.instance, "str"), null);
    ByteComparable bOne1 = typeToComparable(t1, vOne);
    ByteComparable bOne2 = typeToComparable(t2, vOne);
    ByteComparable bOneAndNull2 = typeToComparable(t2, vOneAndNull);
