    expectNextComponentNull(comparableBytes);
    expectNextComponentValue(comparableBytes, ByteSourceInverse::getString, "b");
    expectNextComponentValue(comparableBytes, ByteSourceInverse::getString, "c");
    assertEquals(ByteSource.TERMINATOR, comparableBytes.next());
    comparableBytes = ByteSource.peekable(ByteSource.withTerminator(ByteSource.TERMINATOR, ByteSource.of("a", version), null, ByteSource.of("c", version)));
    expectNextComponentValue(comparableBytes, ByteSourceInverse::getString, "a");
    expectNextComponentNull(comparableBytes);
    expectNextComponentValue(comparableBytes, ByteSourceInverse::getString, "c");
    assertEquals(ByteSource.TERMINATOR, comparableBytes.next());
    comparableBytes = ByteSource.peekable(ByteSource.withTerminator(ByteSource.TERMINATOR, ByteSource.of("a", version), ByteSource.of("b", version), null));
    expectNextComponentValue(comparableBytes, ByteSourceInverse::getString, "a");
    expectNextComponentValue(comparableBytes, ByteSourceInverse::getString, "b");
    expectNextComponentNull(comparableBytes);
    assertEquals(ByteSource.TERMINATOR, comparableBytes.next());
    comparableBytes = ByteSource.peekable(ByteSource.withTerminator(ByteSource.TERMINATOR, ByteSource.of("a", version), null, null));
